const dictionary=new Map();
for(const row of rows)for(const value of row)dictionary.set(normal(value),row);
dictionary.set(normal('搜索名称 / 产品编号'),rows.find(r=>r[0]==='Search name or code'));
dictionary.set(normal('点击查看详情'),rows.find(r=>r[0]==='View details'));
dictionary.set(normal('未找到匹配产品'),rows.find(r=>r[0]==='No matching watches'));
const completeRows=(window.JXFullTranslations||[]).map(([source,...values])=>({source,values}));
for(const {source,values} of completeRows)if(!dictionary.has(normal(source)))dictionary.set(normal(source),values);
const glossary=new Map([...completeRows.map(({source,values})=>[source,...values.slice(1)]),...rows,...terms].map(row=>[normal(row[0]),row]));
const escape=s=>s.replace(/[.*+?^$()|[\]\\]/g,'\\$&');
const phrasePattern=new RegExp('\\b('+[...glossary.keys()].sort((a,b)=>b.length-a.length).map(escape).join('|')+')\\b','gi');
let locale='en';try{locale=localStorage.getItem('juxiang.language')||''}catch{}
if(!locales.includes(locale)){const language=(navigator.language||'en').toLowerCase();locale=language.startsWith('zh')?'zh-CN':locales.find(l=>language.startsWith(l))||'en'}
const index=()=>locales.indexOf(locale);
const word=en=>dictionary.get(normal(en))?.[index()]||en;
const pageWords={en:['Page','of','selections'], 'zh-CN':['第','/','款腕表 / 配色'],es:['Página','de','selecciones'],fr:['Page','sur','sélections'],de:['Seite','von','Ausführungen'],ar:['صفحة','من','اختياراً']};
function translate(source){
 const raw=source.replace(/\uFE0F/g,'');const trimmed=raw.trim();if(!trimmed)return raw;
 const base=english(trimmed);let row=dictionary.get(normal(trimmed))||dictionary.get(normal(base));
 if(row)return raw.replace(trimmed,row[index()]);
 let numberLabel=base.match(/^(\d+) of (\d+)$/);if(numberLabel)return numberLabel[1]+' '+pageWords[locale][1]+' '+numberLabel[2];
 if(/^0 watches/.test(base))return '0 '+word('Watches');
 let m=base.match(/^(\d+)–(\d+)\s*\/\s*(\d+)\s+selections/i);if(m)return m[1]+'–'+m[2]+' / '+m[3]+' '+pageWords[locale][2];
 m=base.match(/^Page (\d+) of (\d+)/i);if(m){const w=pageWords[locale];return w[0]+' '+m[1]+' '+w[1]+' '+m[2]}
 if(/^Search\s*·/.test(base))return word('Search · Brand / series / colour / code');
 if(/^Explore .*?-style design in the supplied photographs\./.test(base)||/^Choose a colour and swipe through/.test(base))return [
 'Explore the supplied photographs. Swipe to compare colours and scroll down for matching details. Exact specifications are unconfirmed; please enquire.',
 '浏览供图，左右滑动比较配色，下滑查看对应细节。具体规格待确认，请咨询。',
 'Explore las fotos. Deslice para comparar colores y baje para ver los detalles. Confirme las especificaciones al consultar.',
 'Explorez les photos. Balayez pour comparer les couleurs et faites défiler pour les détails. Caractéristiques à confirmer sur demande.',
 'Entdecken Sie die Fotos. Wischen Sie für Farben und scrollen Sie für Details. Genaue Eigenschaften bitte erfragen.',
 'تصفح الصور واسحب لمقارنة الألوان ومرّر لأسفل لرؤية التفاصيل. يرجى الاستفسار لتأكيد المواصفات.'
 ][index()];
 if(/^Selection shown in user-supplied photographs\.|^Seller-supplied photographs\./.test(base))return [
 'Seller-supplied photographs. Names and colours describe appearance only. Confirm the actual item, authenticity, specifications, availability and price before ordering.',
 '照片由卖家提供，名称及颜色仅描述外观。订购前请确认实物、真伪、规格、库存和价格。',
 'Fotos del vendedor. Nombres y colores describen solo la apariencia. Confirme el artículo, autenticidad, especificaciones, disponibilidad y precio antes de pedir.',
 'Photos du vendeur. Noms et couleurs décrivent uniquement l’apparence. Confirmez l’article, l’authenticité, les caractéristiques, le stock et le prix avant commande.',
 'Verkäuferfotos. Namen und Farben beschreiben nur das Erscheinungsbild. Prüfen Sie Artikel, Echtheit, Eigenschaften, Verfügbarkeit und Preis vor Bestellung.',
 'صور مقدمة من البائع. الأسماء والألوان تصف المظهر فقط. تأكد من المنتج وأصالته ومواصفاته وتوفره وسعره قبل الطلب.'
 ][index()];
 if(locale==='zh-CN'&&/[\u3400-\u9fff]/u.test(trimmed)){const part=trimmed.match(/[\u3400-\u9fff].*/u);return part?part[0]:trimmed}
 if(locale==='en')return raw.replace(trimmed,base);
 return raw.replace(trimmed,base.replace(phrasePattern,s=>glossary.get(normal(s))?.[index()]||s));
}
