const icons={'↗':'external','←':'back','→':'forward','↓':'down','↑':'up','‹':'left','›':'right','Ⅱ':'pause','▶':'play'};
function icon(name){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','ui-icon');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',iconPaths[name]);svg.append(path);return svg}
const textCache=new WeakMap(),attributeCache=new WeakMap();
function text(node){
 const previous=textCache.get(node),source=previous&&node.data===previous.last?previous.source:node.data;
 if(/[↗←→↓↑‹›Ⅱ▶]/u.test(source)){
  const fragment=document.createDocumentFragment();for(const part of source.replace(/\uFE0F/g,'').split(/([↗←→↓↑‹›Ⅱ▶])/u)){if(icons[part])fragment.append(icon(icons[part]));else if(part){const translated=translate(part),t=document.createTextNode(translated);textCache.set(t,{source:part,last:translated});fragment.append(t)}}node.replaceWith(fragment);return;
 }
 const last=translate(source);if(node.data!==last)node.data=last;textCache.set(node,{source,last});
}
function walk(root){
 if(root.nodeType===3){if(root.parentElement&&!root.parentElement.closest('script,style,svg,[data-no-translate],.brand-wordmark,.brand-chinese'))text(root);return}
 if(root.nodeType!==1||root.matches('script,style,svg,[data-no-translate]'))return;
 if(root.tagName==='OPTION'&&!root.hasAttribute('value'))root.value=root.textContent;
 for(const attr of ['placeholder','aria-label','title','alt']){
  if(!root.hasAttribute(attr))continue;let cache=attributeCache.get(root);if(!cache){cache={};attributeCache.set(root,cache)}
  const current=root.getAttribute(attr),old=cache[attr],source=old&&current===old.last?old.source:current,last=translate(source);if(current!==last)root.setAttribute(attr,last);cache[attr]={source,last};
 }
 for(const child of [...root.childNodes])walk(child);
}
